15→
16→export type PropertyListProps = React.PropsWithChildren<ComponentProps<'dl'> & {
17→  /** Whether this component should be unstyled. */
18→  unstyled?: undefined | boolean,
19→
20→  /** 
21→   * The orientation of the property's, either horizontal or vertical. 
22→   * 
23→   * Default: `"horizontal"`. 
24→   */
25→  orientation?: undefined | 'horizontal' | 'vertical',
26→}>;
27→export const PropertyList = Object.assign(
28→  ({ unstyled = false, orientation, ...propsRest }: PropertyListProps) => {
29→    return (
30→      <dl
31→        {...propsRest}
32→        className={cx(
33→          {
34→            bk: true,
35→            [cl['bk-property-list']]: !unstyled,
36→            [cl['bk-property-list--horizontal']]: orientation === 'horizontal',
37→            [cl['bk-property-list--vertical']]: orientation === 'vertical',
38→          },
39→          propsRest.className,
40→        )}
41→      />
42→    );
43→  },
44→  { Property: ListProperty },
45→);
