  5→import * as React from 'react';
  6→import { mergeRefs, useEffectOnce, usePrevious } from '../../../../util/reactUtil.ts';
  7→import { classNames as cx, type ComponentProps } from '../../../../util/componentUtil.ts';
  8→import { isItemProgrammaticallyFocusable } from '../../../util/composition/compositionUtil.ts';
  9→
 10→import { Button } from '../../../actions/Button/Button.tsx';
 11→
 12→import cl from './SegmentedControl.module.scss';
 13→
 14→
 15→/*
 16→References:
 17→- https://primer.style/components/segmented-control
 18→- https://canvas.workday.com/components/buttons/segmented-control
 19→- https://github.com/adobe/react-spectrum/discussions/7274
 20→- https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/radiogroup_role
 21→*/
 22→
 23→export { cl as SegmentedControlClassNames };
 24→
 25→
 26→export type ButtonKey = string;
 27→export type ButtonDef = {
 28→  buttonKey: ButtonKey,
 29→  buttonRef: React.RefObject<null | React.ComponentRef<typeof Button>>,
 30→};
 31→
 32→export type SegmentedControlContext = {
 33→  register: (buttonDef: ButtonDef) => () => void,
 34→  selectedButton: undefined | ButtonKey,
 35→  disabled: boolean,
 36→  selectButton: (buttonKey: ButtonKey) => void,
 37→};
 38→export const SegmentedControlContext = React.createContext<null | SegmentedControlContext>(null);
 39→export const useSegmentedControlContext = (buttonDef: ButtonDef) => {
 40→  const context = React.use(SegmentedControlContext);
 41→  if (context === null) { throw new Error(`Missing SegmentedControlContext provider`); }
 42→  
 43→  React.useEffect(() => {
 44→    return context.register(buttonDef);
 45→  }, [context.register, buttonDef]);
 46→  
 47→  return context;
 48→};
 49→
 50→
 51→type SegmentedControlButtonProps = ComponentProps<typeof Button> & {
 52→  /** Whether this component should be unstyled. */
 53→  unstyled?: undefined | boolean,
 54→  
 55→  /** The unique key of this button within the segmented control. */
 56→  buttonKey: ButtonKey,
 57→};
 58→const SegmentedControlButton = (props: SegmentedControlButtonProps) => {
 59→  const { unstyled, buttonKey, ...propsRest } = props;
 60→  
 61→  const buttonRef = React.useRef<React.ComponentRef<typeof Button>>(null);
 62→  const buttonDef = React.useMemo<ButtonDef>(() => ({ buttonKey, buttonRef }), [buttonKey]);
 63→  
 64→  const context = useSegmentedControlContext(buttonDef);
 65→  const isSelected = context.selectedButton === buttonKey;
 66→  
 67→  return (
 68→    <Button
 69→      unstyled
 70→      role="radio"
 71→      aria-checked={isSelected}
 72→      tabIndex={isSelected ? 0 : -1} // "Roving" tab index
 73→      {...propsRest}
 74→      ref={mergeRefs(buttonRef, propsRest.ref)}
 75→      className={cx(
 76→        { [cl['bk-segmented-control__button']]: !unstyled },
 77→        propsRest.className,
 78→      )}
 79→      onPress={() => {
 80→        propsRest.onPress?.();
 81→        context.selectButton(buttonKey);
 82→      }}
 83→      disabled={context.disabled || propsRest.disabled}
 84→    />
 85→  );
 86→};
 87→
 88→export type SegmentedControlProps = ComponentProps<'div'> & {
 89→  /** Whether this component should be unstyled. */
 90→  unstyled?: undefined | boolean,
 91→  
 92→  // Note: currently only supports `small`, but we may introduce a 'medium' default in the future. Make this field
 93→  // required for now so that we can change the default later.
 94→  /** The size of the component. */
 95→  size: 'small',
 96→  
 97→  /** The default button to select. Only relevant for uncontrolled usage (`selected` is `undefined`). */
 98→  defaultSelected?: undefined | ButtonKey,
 99→  
100→  /** The button to select. If `undefined`, this component will be considered uncontrolled. */
101→  selected?: undefined | ButtonKey,
102→  
103→  /** Event handler for segmented control button change events. */
104→  onUpdate?: undefined | ((buttonKey: ButtonKey) => void),
105→  
106→  /** Whether the segmented control is disabled or not. Default: false. */
107→  disabled?: undefined | boolean,
108→  
109→  /** Any additional props to apply to the internal `<input type="hidden"/>`. */
110→  inputProps?: undefined | Omit<React.ComponentProps<'input'>, 'value' | 'onChange'>,
111→};
112→/**
113→ * A segmented control is a set of mutually exclusive buttons that can be switched between.
114→ */
115→export const SegmentedControl = Object.assign(
116→  (props: SegmentedControlProps) => {
117→    const {
118→      children,
119→      unstyled = false,
120→      size = 'small',
121→      defaultSelected,
122→      selected,
123→      disabled = false,
124→      onUpdate,
125→      inputProps = {},
126→      ...propsRest
127→    } = props;
128→    
129→    if (typeof selected !== 'undefined' && !onUpdate) {
130→      console.warn(`Using SegmentedControl as uncontrolled component, but missing 'onChange' callback.`);
131→    }
132→    
133→    const buttonDefsRef = React.useRef<Map<ButtonKey, ButtonDef>>(new Map());
134→    const [selectedButton, setSelectedButton] = React.useState<undefined | ButtonKey>(selected ?? defaultSelected);
135→    
136→    // Sync `selected` prop to internal state
137→    React.useEffect(() => {
138→      if (typeof selected !== 'undefined') {
139→        setSelectedButton(selected);
140→      }
141→    }, [selected]);
142→    
143→    const register = React.useCallback((buttonDef: ButtonDef) => {
144→      const buttonDefs = buttonDefsRef.current;
145→      if (buttonDefs.has(buttonDef.buttonKey)) {
146→        console.error(`Duplicate button key: ${buttonDef.buttonKey}`);
147→      } else {
148→        buttonDefsRef.current.set(buttonDef.buttonKey, buttonDef);
149→      }
150→      
151→      return () => {
152→        buttonDefsRef.current.delete(buttonDef.buttonKey);
153→      };
154→    }, []);
155→    
156→    const selectButton = React.useCallback((buttonKey: ButtonKey) => {
157→      setSelectedButton(selectedButton => {
158→        if (buttonKey !== selectedButton) {
159→          buttonDefsRef.current.get(buttonKey)?.buttonRef.current?.focus();
160→          return buttonKey;
161→        } else {
162→          return selectedButton;
163→        }
164→      });
165→    }, []);
166→    
167→    const selectedButtonPrev = usePrevious(selectedButton);
168→    // biome-ignore lint/correctness/useExhaustiveDependencies: Do not include event callbacks as dep.
169→    React.useEffect(() => {
170→      // Note: selected state should be updated to `undefined`, the `undefined` case should only be possible as an
171→      // initial state. Subsequent updates should always be some value. Just like how native HTML radio groups work.
172→      const isDefined = typeof selectedButton !== 'undefined';
173→      const isInitial = selectedButtonPrev === null; // `null` should only ever mean "not yet set"
174→      
175→      if (isDefined && !isInitial) {
176→        onUpdate?.(selectedButton);
177→      }
178→    }, [selectedButton]);
179→    
180→    // After initial rendering, check whether `defaultSelected` refers to one of the rendered buttons
181→    useEffectOnce(() => {
182→      if (typeof defaultSelected === 'undefined') { return; }
183→      
184→      const buttonDef: undefined | ButtonDef = buttonDefsRef.current.get(defaultSelected);
185→      if (typeof buttonDef === 'undefined' || buttonDef.buttonRef.current === null) {
186→        console.error(`Unable to find a button matching the specified defaultSelected: ${defaultSelected}`);
187→      } else if (!disabled && !isItemProgrammaticallyFocusable(buttonDef.buttonRef.current)) {
188→        console.error(`Default button is not focusable: ${defaultSelected}`);
189→      }
190→    });
191→    
192→    const context = React.useMemo<SegmentedControlContext>(() => ({
193→      register,
194→      selectedButton,
195→      selectButton,
196→      disabled,
197→    }), [register, selectedButton, selectButton, disabled]);
198→    
199→    const handleKeyDown = React.useCallback((event: React.KeyboardEvent) => {
200→      const selectedButton = context.selectedButton;
201→      if (typeof selectedButton === 'undefined') { return; }
202→      
203→      // Get the list of button keys, ideally in the order that they are displayed to the user.
204→      // Filter only the buttons that are (programmatically) focusable.
205→      const buttonKeys: Array<ButtonKey> = [...buttonDefsRef.current.entries()]
206→        .filter(([_, { buttonRef }]) => buttonRef.current && isItemProgrammaticallyFocusable(buttonRef.current))
207→        .map(([buttonKey]) => buttonKey);
208→      
209→      const buttonIndex: number = buttonKeys.indexOf(selectedButton);
210→      if (buttonIndex < 0) {
211→        console.error(`Could not resolve selected button: '${selectedButton}'`);
212→      }
213→      
214→      // Determine the target button to focus based on the keyboard event (if any)
215→      const buttonTarget = ((): null | ButtonKey => {
216→        switch (event.key) {
217→          case 'ArrowLeft': {
218→            const buttonPrevIndex = buttonIndex === 0 ? -1 : buttonIndex - 1;
219→            const buttonPrev: undefined | ButtonKey = buttonKeys.at(buttonPrevIndex);
220→            if (typeof buttonPrev  === 'undefined') { throw new Error(`Should not happen`); }
221→            return buttonPrev;
222→          }
223→          case 'ArrowRight': {
224→            const buttonNextIndex = buttonIndex + 1 >= buttonKeys.length ? 0 : buttonIndex + 1;
225→            const buttonNext: undefined | ButtonKey = buttonKeys.at(buttonNextIndex);
226→            if (typeof buttonNext  === 'undefined') { throw new Error(`Should not happen`); }
227→            return buttonNext;
228→          }
229→          case 'ArrowUp': {
230→            const buttonFirst: undefined | ButtonKey = buttonKeys.at(0);
231→            if (typeof buttonFirst  === 'undefined') { throw new Error(`Should not happen`); }
232→            return buttonFirst;
233→          }
234→          case 'ArrowDown': {
235→            const buttonLast: undefined | ButtonKey = buttonKeys.at(-1);
236→            if (typeof buttonLast  === 'undefined') { throw new Error(`Should not happen`); }
237→            return buttonLast;
238→          }
239→          default: return null;
240→        }
241→      })();
242→      
243→      if (buttonTarget !== null && buttonTarget !== context.selectedButton) {
244→        event.preventDefault();
245→        context.selectButton(buttonTarget);
246→      }
247→    }, [context]);
248→    
249→    return (
250→      <SegmentedControlContext value={context}>
251→        <div
252→          role="radiogroup"
253→          aria-required
254→          aria-orientation="horizontal"
255→          {...propsRest}
256→          className={cx(
257→            'bk',
258→            { [cl['bk-segmented-control']]: !unstyled },
259→            { [cl['bk-segmented-control--small']]: size === 'small' },
260→            { [cl['bk-segmented-control--disabled']]: disabled },
261→            propsRest.className,
262→          )}
263→          onKeyDown={handleKeyDown}
264→        >
265→          {/* Hidden input, so that this component can be connected to a <form> element */}
266→          <input type="hidden" {...inputProps} value={selectedButton} onChange={undefined}/>
267→          
268→          {children}
269→        </div>
270→      </SegmentedControlContext>
271→    );
272→  },
273→  {
274→    Button: SegmentedControlButton,
275→  },
276→);
277→

